# Let's look at connected components of 4s
def find_connected_components(cells, rows, cols):
    visited = set()
    components = []

    for r, c in sorted(cells):
        if (r, c) in visited:
            continue

        component = []
        to_check = [(r, c)]
        while to_check:
            curr_r, curr_c = to_check.pop()
            if (curr_r, curr_c) in visited:
                continue
            visited.add((curr_r, curr_c))
            component.append((curr_r, curr_c))

            # Check neighbors (8-directional)
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if (nr, nc) not in visited and (nr, nc) in cells:
                            if (nr, nc) not in component:
                                to_check.append((nr, nc))

        components.append(component)
    return components

